const URL_COMENTARIOS="/api/comentarios";export async function enviarComentario(o){const n=await fetch(URL_COMENTARIOS,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(o)});if(!n.ok){const o=await n.json().catch(()=>({}));throw new Error(o.error||"No se pudo guardar el comentario.")}return n.json()}export async function obtenerComentarios(){const o=await fetch(URL_COMENTARIOS);if(!o.ok)throw new Error("No se pudieron obtener los comentarios.");return o.json()}